    while (parent1[x] != x) {
        parent1[x] = parent1[parent1[x]];
        x = parent1[x];
    }
    return x;
}

void union1(int a, int b) {
    a = find1(a);
    b = find1(b);
    if (a == b) return;
    if (size1[a] < size1[b]) {
        int t = a; a = b; b = t;
    }
    parent1[b] = a;
    size1[a] += size1[b];
}

